class Solution:
    def maxJump(self, stones):
        n = len(stones)
        def ok(k):
            a = b = 0
            for s in stones[1:]:
                fa, fb = s - a <= k, s - b <= k
                if not fa and not fb:
                    return False
                if fa and fb:
                    a, b = max(a, b), s
                elif fa:
                    a = s
                else:
                    b = s
            return True
        lo, hi = 0, stones[-1] - stones[0]
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

