class Solution {
public:
    int maxJump(vector<int>& stones) {
        int n = stones.size();
        auto ok = [&](long long k) {
            long long a = 0, b = 0;
            for (int i = 1; i < n; i++) {
                long long s = stones[i];
                bool fa = s - a <= k, fb = s - b <= k;
                if (!fa && !fb) return false;
                if (fa && fb) { a = max(a, b); b = s; }
                else if (fa) a = s;
                else b = s;
            }
            return true;
        };
        long long lo = 0, hi = stones[n-1] - stones[0];
        while (lo < hi) {
            long long mid = (lo + hi) / 2;
            if (ok(mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int)lo;
    }
};

