class Solution {
    public int maxJump(int[] stones) {
        int n = stones.length;
        long lo = 0, hi = stones[n - 1] - stones[0];
        while (lo < hi) {
            long mid = (lo + hi) / 2;
            if (ok(stones, mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int) lo;
    }
    private boolean ok(int[] st, long k) {
        long a = 0, b = 0;
        for (int i = 1; i < st.length; i++) {
            long s = st[i];
            boolean fa = s - a <= k, fb = s - b <= k;
            if (!fa && !fb) return false;
            if (fa && fb) { a = Math.max(a, b); b = s; }
            else if (fa) a = s;
            else b = s;
        }
        return true;
    }
}

